GM_SHIM = r'''
window.GM = {
  getValue: async (k, d) => { const v = localStorage.getItem('gm:' + k); return v === null ? d : v; },
  setValue: async (k, v) => { localStorage.setItem('gm:' + k, v); },
  xmlHttpRequest: (o) => { fetch(o.url, { method: o.method || 'GET', headers: o.headers, body: o.data }).then(async r => {
      const resp = o.responseType === 'blob' ? await r.blob() : null; const txt = o.responseType === 'blob' ? '' : await r.text();
      o.onload && o.onload({ status: r.status, responseText: txt, response: resp || txt, finalUrl: r.url }); }).catch(e => o.onerror && o.onerror(e)); }
};
window.__errs = []; window.addEventListener('error', e => window.__errs.push(String(e.message || e)));
window.addEventListener('unhandledrejection', e => window.__errs.push('rej: ' + String((e.reason && e.reason.message) || e.reason)));
'''

def prefs(extra=None, dark=False):
    now = int(time.time() * 1000)
    p = {'consent': {'v': 3, 't': now}, 'tourSeen': True, 'news': {'last': '9.9.9', 'upto': '9.9.9', 'seen': {}, 'tours': {}}, '_t': now, 'tileLook': 'content'}
    if extra: p.update(extra)
    return p

