def open_page(p, script_path, dev='iphone', url='https://wol.jw.org/ro/wol/d/r34/lp-m/2024123', dark=False, extra=None):
    b = p.chromium.launch()
    ctx = b.new_context(**DEV[dev], color_scheme='dark' if dark else 'light', locale='ro-RO')
    setup_routes(ctx)
    code = open(script_path, encoding='utf-8').read()
    pr = json.dumps(prefs(extra))
    ctx.add_init_script(GM_SHIM + f"try{{localStorage.setItem('jwse:prefs', {json.dumps(pr)});localStorage.setItem('gm:settings', {json.dumps(pr)});}}catch(e){{}}\n")
    ctx.add_init_script(code)
    page = ctx.new_page()
    logs = []
    page.on('console', lambda m: logs.append(f'{m.type}: {m.text}') if m.type in ('error', 'warning') else None)
    page.on('pageerror', lambda e: logs.append('pageerror: ' + str(e)))
    page.goto(url); page.wait_for_timeout(1500)
    return b, ctx, page, logs

